export function initializeExperience(){
 const $=id=>document.getElementById(id),main=$('overview'),nav=$('main-nav');
 document.body.classList.add('immersive');
 const scope=document.createElement('details');scope.className='scope-drawer';const summary=document.createElement('summary');summary.textContent=`${$('date-from').value} → ${$('date-to').value} · Selection & comparison`;scope.append(summary);
 const all=[...main.children];let collecting=false;
 for(const node of all){if(node.id==='dashboard')collecting=true;if(node.id==='data-note')collecting=false;if(collecting)scope.append(node)}
 main.querySelector('header').after(scope);scope.querySelector('#dashboard').id='dashboard-controls';scope.id='dashboard';
 let view='overview';for(const node of [...main.children]){if(node.matches('header,footer')||node===scope)continue;if(node.classList.contains('intro'))view='overview';if(node.id==='data-note')view='dashboard';if(['ask-data','insights','campaign-health','budget-planner','funnel-explorer','campaigns','reports','data-studio','about'].includes(node.id))view=node.id;node.dataset.view=view}
 const titles={overview:'Your command center',dashboard:'Performance', 'ask-data':'Ask Your Data',insights:'Strategy Lab','campaign-health':'Campaign Health','budget-planner':'Budget Planner','funnel-explorer':'Funnel Explorer',campaigns:'Campaign Explorer',reports:'Reports','data-studio':'Data Studio',about:'Project details'};
 const crumb=main.querySelector('header>div');crumb.className='workspace-heading';crumb.textContent='Your command center';
 const jump=document.createElement('div');jump.className='launch-grid';jump.dataset.view='overview';[['dashboard','01','Understand performance','Start with the numbers. Find what changed.'],['ask-data','02','Ask a sharper question','Explore the evidence behind the signal.'],['insights','03','Choose your next move','Build one focused, measurable test.']].forEach(([id,icon,title,text])=>{const a=document.createElement('a');a.href='#'+id;const i=document.createElement('span');i.className='launch-icon';i.textContent=icon;const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=text;a.append(i,h,p);jump.append(a)});main.querySelector('.intro').after(jump);jump.after(scope);const heading=document.createElement('div');heading.className='chapter-heading';heading.innerHTML='<span>01 / MEASURE</span><h2>Start with your performance.</h2><p>Choose a period, review the signal, then ask what it means.</p>';scope.before(heading);
 function disclose(node,label){if(!node)return;const d=document.createElement('details');d.className='depth-drawer';const s=document.createElement('summary');s.textContent=label;node.before(d);d.append(s,node);node.addEventListener('invalid',()=>d.open=true,true);return d}
 disclose($('expanded-metrics'),'Explore efficiency metrics');
 disclose($('structured-strategy'),'Recommendation · evidence & reasoning');
 const tools=document.querySelector('.strategy-tools');if(tools){[...tools.children].forEach((card,i)=>disclose(card,i?'Quick budget scenario':'Create an experiment'));}
 disclose($('action-plan'),'Your action checklist');
 const goals=document.querySelector('.breakdown .goal-controls');if(goals)disclose(goals,'Adjust margin & acquisition goals');
 const healthGoals=$('campaign-health').querySelector('.goal-controls');disclose(healthGoals,'Adjust scoring goals');
 document.querySelectorAll('p.hint').forEach(p=>{if(p.textContent.length>180&&!p.id&&!p.closest('details'))disclose(p,'Method & limitations')});
 const descriptions={'ask-data':'One question. Clear evidence. A practical next step.','insights':'Find a signal, choose a test, measure the outcome.','campaign-health':'See which campaigns meet your goals.','budget-planner':'Explore your options before committing spend.','reports':'Build a focused summary of your current selection.','data-studio':'Bring your data. Preview it before it becomes your analysis.'};
 for(const [id,text]of Object.entries(descriptions)){const p=$(id).querySelector(':scope > p:not([id])');if(p)p.textContent=text}
 const intro=document.querySelector('.intro-sub');intro.textContent='A calm space to understand performance and decide what comes next.';document.querySelector('.intro-actions .text-link').href='#ask-data';document.querySelector('.intro-actions .text-link').textContent='Ask your data ↗';document.querySelector('.intro-actions .button').href='#dashboard';
 // Continuous page: links navigate to sections; the sidebar follows your reading position.
 document.querySelectorAll('main>[data-view]').forEach(n=>n.hidden=false);main.dataset.workspace='continuous';crumb.textContent='Campaign intelligence';
 function activate(){const id=location.hash.slice(1)||'overview';if(id==='dashboard')scope.open=true;const target=$(id);if(target){let parent=target.closest('details');if(parent)parent.open=true;target.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}}
 window.addEventListener('hashchange',activate);if(location.hash)requestAnimationFrame(activate);
 const links=[...nav.querySelectorAll('a')];let queued=false;
 function updateNav(){queued=false;let active='overview';for(const a of links.slice(1)){const n=$(a.hash.slice(1));if(n&&n.getBoundingClientRect().top<window.innerHeight*.35)active=a.hash.slice(1)}links.forEach(a=>{const selected=a.hash==='#'+active;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}
 window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(updateNav)}},{passive:true});updateNav();
 const chapterTitles={'ask-data':['02 / UNDERSTAND','Explore what the numbers mean.'],'insights':['03 / ACT','Make the next move measurable.']};for(const [id,[step,title]]of Object.entries(chapterTitles)){const h=document.createElement('div');h.className='chapter-heading';const label=document.createElement('span');label.textContent=step;const text=document.createElement('h2');text.textContent=title;h.append(label,text);$(id).before(h)}
 document.querySelector('.intro-lead').textContent='Understand your campaigns. Find the signal. Decide what to test next.';
 document.querySelector('.intro-sub').textContent='Your marketing decision workspace — from clear evidence to a practical next step.';
 const brand=document.querySelector('.brand');brand.setAttribute('aria-label','Marketing Insights AI home');
 const paths={overview:'M3 10 12 3l9 7v10H3z',dashboard:'M4 20V10m8 10V4m8 16v-7', 'ask-data':'M12 3 14 9l7 3-7 3-2 6-2-6-7-3 7-3z',insights:'M9 3h6m-5 0v6L4 19q-1 2 2 2h12q3 0 2-2l-6-10V3M8 14h8','campaign-health':'M3 12h4l3-7 4 14 3-7h4','budget-planner':'M4 7h16v14H4zM8 7V3h8v4m-8 7h8','funnel-explorer':'M3 4h18l-7 8v8l-4-2v-6z',campaigns:'M4 5h16v15H4zM4 10h16M10 10v10',reports:'M6 3h9l4 4v14H6zM10 12h5m-5 4h5','data-studio':'M4 6c0-4 16-4 16 0s-16 4-16 0m0 0v12c0 4 16 4 16 0V6M4 12c0 4 16 4 16 0'};
 for(const a of links){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.classList.add('nav-icon');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',paths[a.hash.slice(1)]||paths.dashboard);svg.append(path);a.prepend(svg)}
 function rangeState(){const value=$('date-preset').value;for(const [id,key]of [['range7','7'],['range30','30'],['rangeall','all']])$(id).setAttribute('aria-pressed',String(value===key));const custom=$('comparison-mode').value==='custom';for(const id of ['comparison-from','comparison-to'])$(id).parentElement.hidden=!custom}
 $('comparison-mode').addEventListener('change',rangeState);$('date-preset').addEventListener('change',rangeState);['range7','range30','rangeall','date-from','date-to'].forEach(id=>$(id).addEventListener(id.startsWith('date-')?'change':'click',()=>requestAnimationFrame(rangeState)));document.addEventListener('mi:context',()=>requestAnimationFrame(rangeState));rangeState();
 document.addEventListener('mi:context',e=>{const c=e.detail;summary.textContent=`${c.filters.from} → ${c.filters.to} · ${c.filters.channel||'All channels'} · Selection & comparison`});
}
